// Bank logo dimensions and asset
// Source: User-provided reference image media_1792529604839.png
// Flattened on #FFFFFF, 561x600 px, 4:4:4 chroma subsampling, ultra-crisp

export const BANK_LOGO_WIDTH = 561;
export const BANK_LOGO_HEIGHT = 600;
export const BANK_LOGO_ASPECT_RATIO = 561 / 600; // ~0.935

export const BANK_LOGO_JPEG_BASE64 = "";

let cachedBytes: Uint8Array | null = null;

export function getBankLogoJpegBytes(): Uint8Array {
  if (cachedBytes) return cachedBytes;
  const bin = atob(BANK_LOGO_JPEG_BASE64);
  const len = bin.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = bin.charCodeAt(i);
  }
  cachedBytes = bytes;
  return cachedBytes;
}
